def _H(bl, text, start=0):
    for i in range(start, len(bl)):
        if bl[i][0] == 'h' and re.sub(r'\s+', ' ', bl[i][2]).strip() == text: return i
    raise KeyError(text)
# heading text, in handout order; each is searched after the previous one, so the repeated heading 'PYQ' resolves to the right block
_SEQ = (('u', '1 · UNIVERSE'), ('de', '2 · DARK ENERGY & DARK MATTER'), ('gal', '3 · GALAXIES'), ('star', '4 · STARS'), ('ss', '5 · SOLAR SYSTEM'), ('pq6', '6 · PYQ'),
        ('pl', '7 · PLANETS'), ('sun', '8 · THE SUN'), ('evo', '9 · EVOLUTION OF EARTH'), ('ef', '10 · EARTH FACTS:'), ('moon', '11 · MOON'), ('ecl', '12 · ECLIPSES:'),
        ('pq13', '13 · PYQ'), ('int', '14 · INTERIOR OF THE EARTH'), ('ipq', 'PYQ'), ('eq', '15 · EARTHQUAKES'), ('em', '17 · EARTH MOVEMENTS'), ('empq', 'PYQ'),
        ('cd', '18 · CONTINENTAL DRIFT & SEA FLOOR SPREAD THEORIES'), ('cdpq', 'PYQ'), ('pt', '19 · PLATE TECTONICS THEORY'), ('ptpq', 'PYQ'), ('vol', '20 · VOLCANISM'),
        ('volpq', 'PYQ'), ('oro', '21 · OROGENY'), ('rock', '22 · ROCKS & ROCK CYCLE'), ('rockpq', 'PYQ'), ('ce', '23 · CYCLES OF EROSION'), ('karst', 'KARST CYCLE:'),
        ('mar', 'MARINE CYCLE:'), ('gla', 'GLACIAL CYCLE:'), ('arid', 'ARID CYCLE:'), ('pq24', '24 · PYQ'), ('rec', 'Recall sheet'))
def _marks(bl):
    M = {}; pos = 0
    for k, t in _SEQ:
        M[k] = _H(bl, t, pos); pos = M[k] + 1
    return M
def drop(bl):
    M = _marks(bl); d = set()
    for a, b in ((M['pq6'], M['pl']), (M['pq13'], M['int']), (M['ipq'], M['eq']), (M['empq'], M['cd']), (M['cdpq'], M['pt']), (M['ptpq'], M['vol']),
                 (M['volpq'], M['oro']), (M['rockpq'], M['ce']), (M['pq24'], len(bl))):
        d.update(range(a, b))
    return d
